package com.tapeverify.copilot.service; import com.fasterxml.jackson.databind.ObjectMapper; import com.tapeverify.copilot.entity.*; import com.tapeverify.copilot.repository.*; import com.tapeverify.copilot.util.HashUtil; import java.time.LocalDateTime; import java.util.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class VerificationService {private final LoanRepository loans;private final VerifiedLoanRepository verified;private final ReviewerActionRepository actions;private final ValidationExceptionRepository exceptions;private final AuditService audit;private final ObjectMapper json;public VerificationService(LoanRepository loans,VerifiedLoanRepository verified,ReviewerActionRepository actions,ValidationExceptionRepository exceptions,AuditService audit,ObjectMapper json){this.loans=loans;this.verified=verified;this.actions=actions;this.exceptions=exceptions;this.audit=audit;this.json=json;}@Transactional public VerifiedLoan decide(Long id,Long exceptionId,String action,String comment){Loan loan=loans.findById(id).orElseThrow(()->new IllegalArgumentException("Loan not found"));String normalizedAction=action==null?"COMMENT":action.trim().toUpperCase(Locale.ROOT);if(!Set.of("COMMENT","REQUEST_CORRECTION","REJECT","APPROVE").contains(normalizedAction))throw new IllegalArgumentException("Unsupported review action");String actor=SecurityContextHolder.getContext().getAuthentication().getName();ValidationException exception=exceptionId==null?null:exceptions.findById(exceptionId).orElseThrow(()->new IllegalArgumentException("Exception not found"));if(exception!=null&&!exception.getLoan().getId().equals(id))throw new IllegalArgumentException("Exception does not belong to this loan");actions.save(ReviewerAction.builder().loan(loan).exception(exception).action(normalizedAction).commentText(comment).actor(actor).createdAt(LocalDateTime.now()).build());if("REJECT".equals(normalizedAction)){loan.setStatus(LoanStatus.REJECTED);loans.save(loan);audit.record(loan,AuditAction.LOAN_REJECTED,actor,null,null);return null;}if(!"APPROVE".equals(normalizedAction)){audit.record(loan,AuditAction.REVIEWER_COMMENT,actor,null,null);return null;}if(!exceptions.findByLoanIdAndResolvedFalse(id).isEmpty())throw new IllegalArgumentException("Resolve all exceptions before approval");if(verified.findByLoanId(id).isPresent())throw new IllegalArgumentException("Loan is already verified");try{loan.setStatus(LoanStatus.VERIFIED);loan.setSha256Hash(HashUtil.hash(loan));loans.save(loan);VerifiedLoan result=verified.save(VerifiedLoan.builder().loan(loan).verifiedBy(actor).verifiedAt(LocalDateTime.now()).decision("APPROVED").canonicalDetails(json.writeValueAsString(com.tapeverify.copilot.dto.AuditLoanSnapshotDto.from(loan))).recordHash(loan.getSha256Hash()).build());audit.record(loan,AuditAction.LOAN_APPROVED,actor,null,null);audit.record(loan,AuditAction.VERIFIED_RECORD_CREATED,actor,null,null);return result;}catch(Exception e){throw new IllegalStateException("Could not create verified record",e);}}public List<Map<String,Object>> actions(Long id){return actions.findByLoanIdOrderByCreatedAtAsc(id).stream().map(a->Map.<String,Object>of("id",a.getId(),"action",a.getAction(),"comment",a.getCommentText()==null?"":a.getCommentText(),"actor",a.getActor(),"createdAt",a.getCreatedAt())).toList();}}
